WITH selected_users AS ( SELECT id FROM order_user WHERE id IN
#{userId}
), self_commissions AS ( SELECT gtf.user_id, SUM(gtf.transaction_amount) AS amount FROM goods_transaction_flow gtf JOIN selected_users su ON su.id = gtf.user_id WHERE gtf.transaction_type = 'fy' AND gtf.created_time >= #{startUtc} AND gtf.created_time < #{endUtc} GROUP BY gtf.user_id ), parent_commissions AS ( SELECT oi.user_id, SUM(gtf.transaction_amount) AS amount FROM goods_transaction_flow gtf JOIN order_info oi ON oi.order_number = SUBSTRING(gtf.remark, 20) JOIN selected_users su ON su.id = oi.user_id WHERE gtf.transaction_type = 'xjfy' AND gtf.remark = CONCAT('child-order-rebate:', oi.order_number) AND gtf.created_time >= #{startUtc} AND gtf.created_time < #{endUtc} GROUP BY oi.user_id ), withdrawals AS ( SELECT ow.user_id, COUNT(*) AS total FROM order_withdrawal ow JOIN selected_users su ON su.id = ow.user_id WHERE ow.create_time >= #{startUtc} AND ow.create_time < #{endUtc} GROUP BY ow.user_id ) SELECT su.id AS userId, COALESCE(sc.amount, 0) AS todayCommission, COALESCE(pc.amount, 0) AS todayParentCommission, COALESCE(w.total, 0) AS todayWithdrawalCount FROM selected_users su LEFT JOIN self_commissions sc ON sc.user_id = su.id LEFT JOIN parent_commissions pc ON pc.user_id = su.id LEFT JOIN withdrawals w ON w.user_id = su.id
